/*
 * prog44_miller_rabin.c
 *
 * Behaviour reproduced from the original binary:
 *
 *   - If no command‑line argument is supplied, prints "NO_INPUT".
 *   - If the argument cannot be parsed as a base‑10 integer, prints "BAD_INPUT".
 *   - If the parsed value is larger than 0xBFA17DC6 (3215031750), prints "OUT_OF_RANGE".
 *   - If the value is less than 2, prints "NOT_PRIME".
 *   - Otherwise runs a deterministic Miller‑Rabin test with the bases
 *     {2,3,5,7,11,13}.  If the number passes all tests it prints "PRIME",
 *     otherwise it prints "NOT_PRIME".
 *
 * All output is performed with `puts`, exactly matching the original binary.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <inttypes.h>

static uint64_t mul_mod(uint64_t a, uint64_t b, uint64_t mod)
{
    /* 128‑bit intermediate product – safe on all modern x86‑64 compilers */
    __uint128_t res = ( __uint128_t ) a * b;
    return (uint64_t)(res % mod);
}

/* fast modular exponentiation (base^exp mod mod) */
static uint64_t pow_mod(uint64_t base, uint64_t exp, uint64_t mod)
{
    uint64_t result = 1 % mod;
    base %= mod;

    while (exp) {
        if (exp & 1)
            result = mul_mod(result, base, mod);
        base = mul_mod(base, base, mod);
        exp >>= 1;
    }
    return result;
}

/* deterministic Miller‑Rabin for n ≤ 0xBFA17DC6 using bases 2,3,5,7,11,13 */
static int is_prime(uint64_t n)
{
    static const uint64_t bases[6] = {2, 3, 5, 7, 11, 13};

    if (n < 2)
        return 0;
    if (n % 2 == 0)
        return n == 2;

    /* write n‑1 as d·2^s with d odd */
    uint64_t d = n - 1;
    unsigned int s = 0;
    while ((d & 1) == 0) {
        d >>= 1;
        ++s;
    }

    for (size_t i = 0; i < 6; ++i) {
        uint64_t a = bases[i];
        if (a % n == 0)          /* base equal to n is irrelevant */
            continue;

        uint64_t x = pow_mod(a, d, n);
        if (x == 1 || x == n - 1)
            continue;

        int composite = 1;
        for (unsigned int r = 1; r < s; ++r) {
            x = mul_mod(x, x, n);
            if (x == n - 1) {
                composite = 0;
                break;
            }
        }
        if (composite)
            return 0;            /* definitely composite */
    }
    return 1;                    /* passed all bases → prime */
}

int main(int argc, char *argv[])
{
    const uint64_t LIMIT = 0xBFA17DC6ULL;   /* 3215031750 */

    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    char *endptr = NULL;
    uint64_t n = strtoll(argv[1], &endptr, 10);

    /* strtoll stops at the first non‑digit; we must have consumed the whole argument */
    if (endptr == NULL || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    if (n > LIMIT) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    if (is_prime(n))
        puts("PRIME");
    else
        puts("NOT_PRIME");

    return 0;
}
